SELECT suizamente_private.write_question($sz_question${"id":"game-1-v1","category":"administracion","difficulty":1,"scope":"CH","canton":null,"status":"published","language":"es","prompt":"Te mudas de Winterthur a Lucerna. ¿Dónde tienes que registrar tu nuevo domicilio?","options":["En el consulado de tu país","En la oficina de habitantes de tu nuevo municipio","En Correos, al cambiar tu dirección","En ningún sitio si tu permiso sigue vigente"],"correct_index":1,"explanation":"Tienes que darte de alta en la oficina de habitantes (Einwohnerkontrolle o contrôle des habitants) del nuevo municipio y de baja en el anterior. El plazo suele ser de 14 días: compruébalo en la web de tu municipio. Cambiar la dirección en Correos solo redirige tus cartas.","source_url":"https://www.ch.ch/en/foreign-nationals-in-switzerland/living-in-switzerland/moving-to-switzerland/","source_title":"ch.ch · Mudanza","reviewed_at":"2026-11-13","game_type":"choice","game_only":true}$sz_question$::jsonb) WHERE NOT EXISTS (SELECT 1 FROM suizamente_private.questions WHERE id='game-1-v1');
SELECT suizamente_private.write_question($sz_question${"id":"game-2-v1","category":"sociedad","difficulty":1,"scope":"canton","canton":"ZH","status":"published","language":"es","prompt":"En el cantón de Zürich, ¿qué red reúne trenes, tranvías, autobuses y barcos con billetes por zonas?","options":["ZVV","TPG","Libero","BLT"],"correct_index":0,"explanation":"El ZVV (Zürcher Verkehrsverbund) organiza el transporte público de todo el cantón con un sistema de zonas. TPG es la empresa de transporte de Ginebra, Libero la comunidad tarifaria de Berna y Soleura, y BLT opera en Basilea-Campiña.","source_url":"https://www.zvv.ch/zvv/en/home.html","source_title":"zvv.ch","reviewed_at":"2026-11-13","game_type":"choice","game_only":true}$sz_question$::jsonb) WHERE NOT EXISTS (SELECT 1 FROM suizamente_private.questions WHERE id='game-2-v1');
