SELECT suizamente_private.write_question($sz_question${"id":"game-4-v1","category":"administracion","difficulty":1,"scope":"canton","canton":"ZH","status":"published","language":"es","prompt":"¿Cómo se llama el parlamento del cantón de Zürich, que aprueba las leyes cantonales?","options":["Grosser Rat","Kantonsrat","Landrat","Stadtrat"],"correct_index":1,"explanation":"En Zürich el parlamento cantonal es el Kantonsrat, con 180 miembros. Otros cantones usan otros nombres, como Grosser Rat en Berna o Landrat en Basilea-Campiña. El Stadtrat es el gobierno de la ciudad, no del cantón.","source_url":"https://www.zh.ch/de/politik-staat/kantonsrat.html","source_title":"zh.ch · Kantonsrat","reviewed_at":"2026-11-13","game_type":"choice","game_only":true}$sz_question$::jsonb) WHERE NOT EXISTS (SELECT 1 FROM suizamente_private.questions WHERE id='game-4-v1');
